import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = rb();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = rb();
        StringBuilder sb = new StringBuilder();
        while (c != -1 && c != ' ' && c != '\n' && c != '\r' && c != '\t') {
            sb.append((char) c);
            c = rb();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        String[] rows = new String[n];
        for (int i = 0; i < n; i++) rows[i] = next();
        // groups[i]: id of row i's prefix class; refine by (old group, next character) each column.
        int[] groups = new int[n], next = new int[n], counts = new int[n];
        int[] ids = new int[n * 256], touched = new int[n];
        Arrays.fill(ids, -1);
        StringBuilder sb = new StringBuilder();
        for (int j = 0; j < m; j++) {
            int made = 0, best = 0;
            for (int i = 0; i < n; i++) {
                int key = groups[i] * 256 + (rows[i].charAt(j) & 0xFF);
                if (ids[key] < 0) {
                    ids[key] = made;
                    touched[made] = key;
                    counts[made++] = 0;
                }
                next[i] = ids[key];
                best = Math.max(best, ++counts[next[i]]);
            }
            for (int g = 0; g < made; g++) ids[touched[g]] = -1;
            int[] t = groups;
            groups = next;
            next = t;
            sb.append(best).append(j + 1 < m ? ' ' : '\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func readToken() string {
	c, err := reader.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = reader.ReadByte()
	}
	var tok []byte
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		tok = append(tok, c)
		c, err = reader.ReadByte()
	}
	return string(tok)
}

func main() {
	n, m := readInt(), readInt()
	rows := make([]string, n)
	for i := range rows {
		rows[i] = readToken()
	}
	// groups[i]: id of row i's prefix class; refine by (old group, next character) each column.
	groups, next, counts := make([]int, n), make([]int, n), make([]int, n)
	ids, touched := make([]int, n*256), make([]int, 0, n)
	for i := range ids {
		ids[i] = -1
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for j := 0; j < m; j++ {
		made, best := 0, 0
		for i := 0; i < n; i++ {
			key := groups[i]*256 + int(rows[i][j])
			if ids[key] < 0 {
				ids[key] = made
				counts[made] = 0
				made++
				touched = append(touched, key)
			}
			next[i] = ids[key]
			counts[next[i]]++
			best = max(best, counts[next[i]])
		}
		for _, key := range touched {
			ids[key] = -1
		}
		touched = touched[:0]
		groups, next = next, groups
		w.WriteString(strconv.Itoa(best))
		if j+1 < m {
			w.WriteByte(' ')
		} else {
			w.WriteByte('\n')
		}
	}
}
